// 依嚴重度決定：none / low 只發「審查通過」通知；medium / high / 無法判讀 → 放到 PR 或 issue 並通知
// Gitea 網址：留空就從 remote 網址推算（remote 要是 http/https）；用 SSH remote 時要填，例如 'https://git.example.com'
const GITEA = '';
// label 名稱：同時列 Gitea「Default」和「Advanced」範本的名稱，repo 和組織裡都沒有的名稱 Gitea 會略過
const LABELS = {
  always: ['ai-review', 'bug', 'Kind/Bug'],
  資安: ['Kind/Security'],
  業務規則: ['Compat/Breaking'],
  high: ['Priority/High'],
  medium: ['Priority/Medium'],
};
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  const review = String(b.review || '');
  // 報告開頭是 <!-- SEVERITY: high --> 和 <!-- FINDINGS: high/資安 medium/正確性 --> 兩行註解
  const m1 = review.match(/SEVERITY:\s*(none|low|medium|high)\b/i);
  const severity = m1 ? m1[1].toLowerCase() : 'unknown';
  const pass = severity === 'none' || severity === 'low';
  const m = String(b.remote || '').match(/[:/]([^/:]+)\/([^/]+?)(?:\.git)?\/?$/);
  if (!m) throw new Error('無法從 remote 解析 owner/repo：' + b.remote);
  const gitea = GITEA || (String(b.remote).match(/^(https?:\/\/.+?)\/[^/]+\/[^/]+?(?:\.git)?\/?$/) || [])[1];
  if (!gitea) throw new Error('remote 不是 http(s) 網址，請在 Parse 節點填 GITEA：' + b.remote);
  const repo = `${m[1]}/${m[2]}`;
  const api = `${gitea}/api/v1/repos/${repo}`;
  const branch = String(b.branch || '');
  const sha = String(b.sha || '');
  const base = String(b.base || '');
  const commits = String(b.commits || '').trim();
  const author = String(b.author || '');
  const email = (author.match(/<([^>]+)>/) || [])[1] || '';
  // 分類 label 只看 medium 以上的發現，避免 low 的「規則檔需更新」也被貼上 Compat/Breaking
  const findings = (review.match(/FINDINGS:([^>]*)-->/) || [])[1] || '';
  const cats = new Set([...findings.matchAll(/(?:high|medium)\/(\S+)/gi)].map(x => x[1]));
  const labels = [...LABELS.always, ...[...cats].flatMap(c => LABELS[c] || []), ...(LABELS[severity] || LABELS.medium)];
  // 通知用的摘要，例如「高 1（資安）、中 2（正確性、效能）」
  const all = [...findings.matchAll(/(high|medium|low)\/(\S+)/gi)].map(x => [x[1].toLowerCase(), x[2]]);
  const summary = [['high', '高'], ['medium', '中'], ['low', '低']].map(([s, zh]) => {
    const c = all.filter(x => x[0] === s).map(x => x[1]);
    return c.length ? `${zh} ${c.length}（${[...new Set(c)].join('、')}）` : '';
  }).filter(Boolean).join('、') || '見報告';
  const compareUrl = `${gitea}/${repo}/compare/${base}...${sha}`;
  out.push({ json: {
    pass,
    summary,
    compareUrl,
    severity,
    repo,
    api,
    branch,
    sha,
    email,
    authorName: author,
    giteaUser: String(b.giteaUser || '').trim(),
    labels,
    // ponytail: 只看前 50 筆開著的 PR，專案量大再改分頁
    prsUrl: `${api}/pulls?state=open&limit=50`,
    searchUrl: `${gitea}/api/v1/users/search?limit=5&q=${encodeURIComponent(email)}`,
    title: `[AI Review][${severity}] ${branch} ${sha.slice(0, 8)}`,
    body: [
      `- 分支：\`${branch}\`（${commits ? commits.split('\n').length : 0} 個 commit，比較：${compareUrl}）`,
      `- push 的人：${author}`,
      `- 審查引擎：${b.engine || ''}`,
      '',
      '<details><summary>這次審查的 commit</summary>',
      '',
      commits,
      '',
      '</details>',
      '',
      review,
    ].join('\n'),
  } });
}
return out;

// 決定結果放哪裡：分支有開著的 PR → 留 PR review；沒有 → 每次都開新 issue，指派給 push 的人
const p = $('Parse').item.json;
const list = r => (r && Array.isArray(r.body) ? r.body : []);
const pr = list($('Find PR').item.json).find(x => x.head && x.head.ref === p.branch);
const users = $json.body && Array.isArray($json.body.data) ? $json.body.data : [];
const hit = users.find(u => p.email && (u.email || '').toLowerCase() === p.email.toLowerCase())
  || (p.email && users.length === 1 ? users[0] : null);
const assignee = p.giteaUser || (hit ? hit.login : '');
const body = `## AI Code Review：${p.severity}（${p.sha.slice(0, 8)}）\n\n${p.body}`;
let out;
if (pr) {
  // high 用「要求修改」；PR 作者剛好是 token 的帳號時 Gitea 不允許，失敗就改成一般留言
  const postBody = { event: p.severity === 'high' ? 'REQUEST_CHANGES' : 'COMMENT', body };
  out = { mode: 'pr', number: pr.number, link: pr.html_url, postUrl: `${p.api}/pulls/${pr.number}/reviews`,
    postBody, fallbackBody: { ...postBody, event: 'COMMENT' } };
} else {
  // 指派的帳號沒有權限時建立會失敗，失敗就改成不指派
  out = { mode: 'issue', number: 0, link: '', postUrl: `${p.api}/issues`,
    postBody: { title: p.title, body, assignees: assignee ? [assignee] : [] },
    fallbackBody: { title: p.title, body } };
}
return { json: { ...p, ...out, assignee } };

// 組 Telegram 訊息（HTML 格式）。連結放在訊息文字裡，Gitea 只有 http 也點得開
// Telegram 的 HTML 格式要把文字裡的 < > & 換成 HTML entity，連結網址裡的 " 也要換
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const name = a => a.replace(/\s*<[^>]*>$/, '');   // 「王小明 <ming@x>」只留名字
const msg = (p, title, rows, linkText, link) => ({ telegram: {
  text: [`<b>${esc(title)}</b>`, esc(`${p.repo} · ${p.branch} · ${p.sha.slice(0, 8)}`), '',
    ...rows.map(([k, v]) => `${k}：${esc(v)}`), '', `<a href="${esc(link)}">${esc(linkText)}</a>`].join('\n'),
  parse_mode: 'HTML',
  link_preview_options: { is_disabled: true },
} });

// 審查通過：從 Passed? 直接過來，$json 是 Parse 的輸出
if ($json.pass) {
  const rows = [['push 的人', name($json.authorName)]];
  if ($json.severity === 'low') rows.push(['備註', '有小建議，報告在 push 的人的電腦']);
  return { json: msg($json, '✅ 審查通過', rows, '查看改動', $json.compareUrl) };
}

// 要處理：從 Post to Gitea 過來，$json 是 Gitea 的回應（PR review 或新 issue）
const b = $('Build').item.json;
const title = { high: '🔴 AI 審查：高風險', medium: '🟠 AI 審查：中風險' }[b.severity] || '⚠️ AI 審查：報告格式無法判讀';
const rows = [['結果', b.mode === 'pr' ? `已在 PR #${b.number} 留下審查` : `已開 issue #${$json.number}`], ['問題', b.summary]];
if (b.mode === 'issue') {
  rows.push(['指派', ($json.assignees || []).map(u => '@' + u.login).join(' ') || `未指派（${name(b.authorName)}）`]);
}
rows.push(['push 的人', name(b.authorName)]);
const linkText = b.mode === 'pr' ? `開啟 PR #${b.number}` : `開啟 issue #${$json.number}`;
return { json: msg(b, title, rows, linkText, b.link || $json.html_url) };
